import{z as i,x as s,o as e,c as C,q as o,j as l,D as A,d as a,s as r,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"条件控制的服务","description":"","frontmatter":{"title":"条件控制的服务","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-control-serving.md","filePath":"llm/diff-control-serving.md","lastUpdated":1791413859000}'),d={name:"llm/diff-control-serving.md"};function p(D,E,F,h,m,f){const B=s("Mermaid");return e(),C("div",null,[E[2]||(E[2]=o('<h1 id="条件控制的服务" tabindex="-1">条件控制的服务 <a class="header-anchor" href="#条件控制的服务" aria-label="Permalink to &quot;条件控制的服务&quot;">​</a></h1><div class="epigraph"><p>文本提示只是条件的一种；把构图、风格、身份都变成可挂载的条件，服务对象就从「一个模型」变成「一个模型加一柜子适配器」。</p><footer>—— 据 Zhang 等 ControlNet（2023）与 IP-Adapter 等适配器实践整理</footer></div><p><a href="/llm/diff-batching-scheduling">上一课</a>把请求凑成桶内同步的批，但那些请求共享同一个条件集。本课把「条件」本身变成服务对象：文本之外，ControlNet 的构图控制、IP-Adapter 的参考图、LoRA 的风格注入都挂在去噪网络上。第一课的条件嵌入缓存在这里推广成条件服务层：凡是纯函数的条件变换，都缓存；凡是可挂载的权重，都按请求装配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多一种条件，管线就多一段会算错账的地方。ControlNet 给去噪网络旁挂一份可训练的编码器副本，每步前向近似翻倍；预处理（边缘图、深度图、姿态）是 CPU 密集的一次性段，不缓存就每请求重算。LoRA 的账更细：底座一份、适配器几十个，逐请求合并有开销，预合并则组合数爆炸；叠加还有权重尺度冲突。缺口是装配协议：请求声明条件集，服务端负责装配、缓存与计价——不立协议，每个功能都以为自己独占管线。</p><p><span class="marginnote">LoRA 直译「低秩适配」：在冻结的大权重旁挂一对很小的矩阵，只训小矩阵。所谓「合并」就是把这对小矩阵的乘积加进大权重。逐请求合并像每次点餐现拼套餐，预合并像把每种组合提前做好放进冰箱——组合一多，冰箱（显存）先爆。</span></p><h3 id="条件的分类与装配" tabindex="-1">条件的分类与装配 <a class="header-anchor" href="#条件的分类与装配" aria-label="Permalink to &quot;条件的分类与装配&quot;">​</a></h3><p>按「算一次还是每步算、挂参数还是挂权重」分四类：</p><ul><li><strong>提示词嵌入</strong>：纯函数，按提示词哈希缓存，命中即省一次文本编码。</li><li><strong>控制图</strong>：预处理是纯函数，按（原图，预处理器，参数）缓存；ControlNet 本体每步都算，进循环段成本。</li><li><strong>适配器权重</strong>：LoRA 按请求装配，合并后的权重短生命周期缓存（键为底座版本 + 适配器集合 + 比例）。</li><li><strong>逐请求标量</strong>：\\(\\gamma\\)、ControlNet 强度、去噪强度，不缓存，进请求校验。</li></ul><p><span class="marginnote">ControlNet 的编码器副本用零卷积初始化接入主干，启用时每步前向的 FLOPs 量级接近翻倍——按请求计价时控制条件不是「附加功能」而是「第二份前向」，定价与配额都要按这个口径。</span></p>',10)),(e(),l(n,null,{default:A(()=>[r(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%8E%A5%E5%85%A5%E4%B8%80%E7%A7%8D%E6%96%B0%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20T%5B%22%E5%85%88%E9%97%AE%E4%B8%A4%E4%BB%B6%E4%BA%8B%3A%20%E6%AF%8F%E6%AD%A5%E9%83%BD%E8%A6%81%E7%AE%97%E5%90%97%3F%20%E6%8C%82%E5%8F%82%E6%95%B0%E8%BF%98%E6%98%AF%E6%8C%82%E6%9D%83%E9%87%8D%3F%22%5D%0A%20%20T%20--%3E%20E%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E7%BA%AF%E5%87%BD%E6%95%B0%3A%20%E6%96%87%E6%9C%AC%E5%B5%8C%E5%85%A5%20%2F%20%E9%A2%84%E5%A4%84%E7%90%86%E5%9B%BE%3Cbr%2F%3E%E6%8C%89%E5%86%85%E5%AE%B9%E5%93%88%E5%B8%8C%E7%BC%93%E5%AD%98%2C%20%E5%91%BD%E4%B8%AD%E5%8D%B3%E7%9C%81%22%5D%0A%20%20T%20--%3E%20B%5B%22%E6%AF%8F%E6%AD%A5%E8%BF%9B%E5%BE%AA%E7%8E%AF%3A%20ControlNet%20%E5%88%86%E6%94%AF%3Cbr%2F%3E%E6%8C%89%E5%8F%8C%E4%BB%BD%E5%89%8D%E5%90%91%E8%AE%A1%E4%BB%B7%E8%BF%9B%E6%A1%B6%22%5D%0A%20%20T%20--%3E%20W%5B%22%E6%8C%82%E6%9D%83%E9%87%8D%3A%20LoRA%3Cbr%2F%3E%E9%80%90%E8%AF%B7%E6%B1%82%E5%90%88%E5%B9%B6%2C%20%E7%9F%AD%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E7%BC%93%E5%AD%98%22%5D%0A%20%20T%20--%3E%20S%5B%22%E6%A0%87%E9%87%8F%E5%BC%BA%E5%BA%A6%3A%20%E5%BC%95%E5%AF%BC%E4%B8%8E%E6%8E%A7%E5%88%B6%E5%B9%85%E5%BA%A6%3Cbr%2F%3E%E4%B8%8D%E7%BC%93%E5%AD%98%2C%20%E8%BF%9B%E8%AF%B7%E6%B1%82%E6%A0%A1%E9%AA%8C%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"方法",tabindex:"-1"},[a("方法 "),t("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("装配协议三步。第一步，请求规格里显式列出条件集：每项控制图带预处理器版本，每个 LoRA 带仓库版本与强度；缺省值由产品档位给，不由服务端猜。第二步，装配器按缓存键取嵌入、控制图与合并权重，未命中项并行补算，预处理在 CPU 池跑，不占 GPU 批位。第三步，把装配结果折算进调度账：启用 ControlNet 的请求换算成更大的等效前向数，进"),t("a",{href:"/llm/diff-batching-scheduling"},"批处理与调度"),a("的桶账，不按普通请求排队。")],-1)),(e(),l(n,null,{default:A(()=>[r(B,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%9D%A1%E4%BB%B6%E9%9B%86%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20CHK%7B%22%E7%BC%93%E5%AD%98%E5%85%A8%E5%91%BD%E4%B8%AD%EF%BC%9F%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20MISS%5B%22%E8%A1%A5%E7%AE%97%EF%BC%9A%E6%96%87%E6%9C%AC%E5%B5%8C%E5%85%A5%20%2F%20%E6%8E%A7%E5%88%B6%E5%9B%BE%20%2F%20LoRA%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20ASM%5B%22%E8%A3%85%E9%85%8D%E6%9D%A1%E4%BB%B6%E5%8C%85%22%5D%0A%20%20MISS%20--%3E%20ASM%0A%20%20ASM%20--%3E%20PRICE%5B%22%E6%8A%98%E7%AE%97%E7%AD%89%E6%95%88%E5%89%8D%E5%90%91%E6%95%B0%22%5D%0A%20%20PRICE%20--%3E%20SCH%5B%22%E8%BF%9B%E8%B0%83%E5%BA%A6%E6%A1%B6%22%5D%0A%20%20SCH%20--%3E%20LOOP%5B%22%E5%8E%BB%E5%99%AA%E5%BE%AA%E7%8E%AF%EF%BC%9A%E4%B8%BB%E5%B9%B2%20%2B%20%E6%9D%A1%E4%BB%B6%E5%88%86%E6%94%AF%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么条件缓存有效而结果缓存廉价：条件到嵌入或控制图是确定性映射，缓存键稳定；而「提示词到成图」的映射还含种子与随机性，结果缓存只在严格复现场景有意义。为什么 LoRA 逐请求合而不是常驻多份：底座权重只读共享，合并产出的临时权重生命周期与请求同长，显存按并发峰值预留；高频组合可以升级为常驻合并变体——这是一个按命中率驱动的缓存晋升问题，不是静态配置。</p><p><span class="marginnote">「命中率驱动的晋升」翻译成零售语言：某组合每秒被点 5 次、每次合并耗时 100 毫秒，现做就要每秒烧掉半个 GPU 用来「备菜」；点得够多就提前备货（常驻合并变体），用一点显存换回整段计算。晋升与否看账本，不看喜好。</span></p><p>为什么引导与控制强度是运营旋钮而不是模型旋钮：它们改变条件分支的注入幅度，不改权重；把「控制不生效」的工单先用强度参数消解，能省掉大量无效的模型回滚。反过来，控制图预处理版本升级会改变所有下游请求的输入分布——预处理器版本必须进请求谱系，与模型版本一起参与归因。</p><p><span class="marginnote">常见误区：收到「ControlNet 不生效」的工单就怀疑模型坏了、急着回滚版本。实际上强度这类标量旋钮先拧一遍——它只改条件注入幅度、不动任何权重，一分钟就能验证；用它消解掉的工单，比一次模型回滚便宜几个数量级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多 ControlNet 的权重调和在模型侧已定，服务端只透传，不发明第二套逻辑；多个 LoRA 的叠加顺序与比例冲突是模型问题，装配层暴露参数但不解决参数。条件服务层不碰安全：参考图与控制图本身要过输入过滤，和提示词同一道门（本课程后面的安全课）。反演类条件（图生图、重绘）引入去噪强度与潜变量复用，这里只声明「条件集可包含初始潜变量」而不展开。最后，装配协议的可观测性是归因的前提：每个请求落盘条件集与缓存命中情况，否则「同一提示词不同结果」永远查不清是种子、装配还是版本的问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件按「算一次还是每步算、挂参数还是挂权重」分四类，各配各的缓存键。</li><li>ControlNet 启用接近双份前向，按等效前向数计价与调度，不当附加功能。</li><li>LoRA 逐请求装配、短生命周期缓存，高频组合按命中率晋升为常驻变体。</li><li>预处理器版本进请求谱系：它改变所有下游输入分布，必须参与归因。</li><li>强度类参数是运营旋钮，先用它消解工单再考虑动模型。</li><li>出处：Zhang 等 ControlNet、IP-Adapter 等适配器文献；装配协议据本课整理。</li></ul>',9))])}const u=i(d,[["render",p]]);export{g as __pageData,u as default};
